package eval

func backupRestoreSuite() Suite {
	base := readinessHealthSuite()
	backup1 := map[string]any{"backup_id": "backup-1", "story": "Story A: the party secures the old keep.", "status": "active"}
	return Suite{ID: "090-backup-restore", Name: "Campaign Play 090: Backup and Restore", Tests: append(base.Tests,
		playTest("play-backup-create-campaign", "DM creates a fresh campaign for backup and restore", "POST", "/v1/play/campaigns", map[string]any{"id": "play-090", "name": "Backup Game", "max_players": 2}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"id": "play-090", "name": "Backup Game", "owner": "dm", "status": "lobby", "max_players": 2}),
		playTest("play-backup-join-player-a", "Player A joins the backup campaign", "POST", "/v1/play/campaigns/play-090/members", map[string]any{"character_id": "play-090-char-a", "name": "Iri", "class": "wizard"}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"username": "player-a", "character_id": "play-090-char-a", "name": "Iri", "class": "wizard"}),
		playTest("play-backup-join-player-b", "Player B joins the backup campaign", "POST", "/v1/play/campaigns/play-090/members", map[string]any{"character_id": "play-090-char-b", "name": "Tovin", "class": "fighter"}, map[string]string{"Authorization": playerBAuth}, 201, map[string]any{"username": "player-b", "character_id": "play-090-char-b", "name": "Tovin", "class": "fighter"}),
		playTest("play-backup-start", "DM starts the backup campaign", "POST", "/v1/play/campaigns/play-090/start", nil, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"id": "play-090", "status": "active", "current_actor": "player-a", "turn_number": 1}),
		playTest("play-backup-player-create-forbidden", "Player cannot create a campaign backup", "POST", "/v1/play/campaigns/play-090/backups", nil, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-backup-player-list-forbidden", "Player cannot list campaign backups", "GET", "/v1/play/campaigns/play-090/backups", nil, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-backup-player-restore-forbidden", "Player cannot restore campaign backups", "POST", "/v1/play/campaigns/play-090/backups/backup-1/restore", nil, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-backup-unknown-restore", "Unknown backup restore returns 404 for owner", "POST", "/v1/play/campaigns/play-090/backups/backup-404/restore", nil, map[string]string{"Authorization": dmAuth}, 404, nil),
		playTest("play-backup-set-story-a", "DM records story A in the campaign document", "PUT", "/v1/play/campaigns/play-090/document", map[string]any{"story": "Story A: the party secures the old keep.", "dm_notes": "A hidden cistern remains."}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"story": "Story A: the party secures the old keep.", "dm_notes": "A hidden cistern remains."}),
		playTest("play-backup-narrate-story-a", "DM narrates story A before taking the backup", "POST", "/v1/play/campaigns/play-090/narrations", map[string]any{"text": "Story A: the party secures the old keep."}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"sequence": 1, "kind": "narration", "actor": "dm", "text": "Story A: the party secures the old keep."}),
		playTestExactJSON("play-backup-create-first", "DM creates immutable backup one from story A", "POST", "/v1/play/campaigns/play-090/backups", nil, map[string]string{"Authorization": dmAuth}, 201, backup1),
		playTest("play-backup-set-story-b", "DM mutates campaign document to story B after backup", "PUT", "/v1/play/campaigns/play-090/document", map[string]any{"story": "Story B: the keep falls under a silver storm.", "dm_notes": "The cistern is flooded."}, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"story": "Story B: the keep falls under a silver storm.", "dm_notes": "The cistern is flooded."}),
		playTest("play-backup-narrate-story-b", "DM narrates story B after backup", "POST", "/v1/play/campaigns/play-090/narrations", map[string]any{"text": "Story B: the keep falls under a silver storm."}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"sequence": 2, "kind": "narration", "actor": "dm", "text": "Story B: the keep falls under a silver storm."}),
		playTestExactJSON("play-backup-document-before-restore", "Campaign document reflects story B before restore", "GET", "/v1/play/campaigns/play-090/document", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"story": "Story B: the keep falls under a silver storm."}),
		playTestExactJSON("play-backup-list-immutable-after-story-b", "Backup list remains ordered and immutable after story B", "GET", "/v1/play/campaigns/play-090/backups", nil, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"backups": []any{backup1}}),
		playTestExactJSON("play-backup-restore-first", "DM restores exact backup one snapshot", "POST", "/v1/play/campaigns/play-090/backups/backup-1/restore", nil, map[string]string{"Authorization": dmAuth}, 200, backup1),
		playTestExactJSON("play-backup-document-after-restore", "Campaign document reflects restored story A", "GET", "/v1/play/campaigns/play-090/document", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"story": "Story A: the party secures the old keep."}),
		playTestExactJSON("play-backup-list-after-restore", "Restore does not mutate or duplicate backup snapshots", "GET", "/v1/play/campaigns/play-090/backups", nil, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"backups": []any{backup1}}),
	)}
}
